import HardsetCore
import SwiftUI

/// The disclosure behind a number.
///
/// App Review guideline 1.4.1 requires an app to "clearly disclose data and methodology to support
/// accuracy claims relating to health measurements", and to reject the app if the methodology
/// cannot be validated. This view renders an `EvidenceSource` verbatim, which means the disclosure
/// is generated by the same values the arithmetic uses and cannot drift from what the code does.
/// Writing this copy by hand in a settings screen is exactly how the two come apart.
///
/// It is also the brand. An app whose claim is calibrated honesty has to be willing to show the
/// limits of its own numbers on the same screen as the numbers.
///
/// Laid out as a document rather than a form: the certainty first, because it is the answer to
/// "how far can I trust this", then the method, then its limits, then the source in a raised card
/// set apart from the prose it supports.
public struct MethodologySheet: View {
  private let source: EvidenceSource
  private let certainty: Certainty?
  /// Every caller presents this as a sheet, so it carries its own way out rather than relying on a
  /// drag a lifter may not know about.
  @Environment(\.dismiss) private var dismiss

  public init(source: EvidenceSource, certainty: Certainty? = nil) {
    self.source = source
    self.certainty = certainty
  }

  public var body: some View {
    NavigationStack {
      ScrollView {
        VStack(alignment: .leading, spacing: Tokens.Spacing.section) {
          if let certainty {
            CertaintyCapsule(level: Self.level(for: certainty), isInteractive: false)
              .accessibilityElement(children: .combine)
          }

          section("How this is calculated", source.methodology)

          if let validRange = source.validRange {
            // Deliberately its own section rather than a parenthetical. The limits of a number are
            // as much a part of the disclosure as the method.
            section("Where this applies, and where it does not", validRange)
          }

          if let citation = source.citation {
            citationCard(citation)
          }
        }
        .padding(.horizontal, Tokens.Spacing.loose)
        .padding(.top, Tokens.Spacing.loose)
        .padding(.bottom, Tokens.Spacing.block)
        .frame(maxWidth: .infinity, alignment: .leading)
      }
      .background(Tokens.Color.canvas)
      .hardsetNavigationTitle(source.title)
      .toolbar {
        ToolbarItem(placement: .confirmationAction) {
          Button("Done") { dismiss() }
        }
      }
    }
  }

  private func section(_ heading: String, _ body: String) -> some View {
    VStack(alignment: .leading, spacing: Tokens.Spacing.snug) {
      Text(heading)
        .font(Tokens.Text.headline)
        .foregroundStyle(Tokens.Color.chalk)
        .accessibilityAddTraits(.isHeader)
      Text(body)
        .font(Tokens.Text.label)
        .foregroundStyle(Tokens.Color.chalk)
        .fixedSize(horizontal: false, vertical: true)
        .textSelection(.enabled)
    }
    .frame(maxWidth: .infinity, alignment: .leading)
  }

  /// The citation, set apart on a raised card. Monospaced so a DOI or PMID can be read back
  /// character by character, and selectable so it can be copied into a search.
  private func citationCard(_ citation: String) -> some View {
    VStack(alignment: .leading, spacing: Tokens.Spacing.snug) {
      Label {
        Text("Source")
      } icon: {
        Image(systemName: "text.book.closed")
          .foregroundStyle(Tokens.Color.chalkDim)
      }
      .font(Tokens.Text.sectionHeader)
      .foregroundStyle(Tokens.Color.chalk)
      .accessibilityAddTraits(.isHeader)
      Text(citation)
        .monospaced()
        .hardsetText(.caption)
        .foregroundStyle(Tokens.Color.chalkDim)
        .fixedSize(horizontal: false, vertical: true)
        .textSelection(.enabled)
    }
    .padding(Tokens.Spacing.regular)
    .frame(maxWidth: .infinity, alignment: .leading)
    .background(
      Tokens.Color.steelRaised,
      in: RoundedRectangle(cornerRadius: Tokens.Radius.card)
    )
    .overlay(
      RoundedRectangle(cornerRadius: Tokens.Radius.card)
        .strokeBorder(Tokens.Color.hairline, lineWidth: Tokens.Stroke.hairline)
    )
  }

  /// Maps engine certainty onto the UI's own scale. Delegates to `CertaintyLevel(_:)`, the one
  /// mapping in the kit, so the progression chart and the muscle map keep their call sites.
  static func level(for certainty: Certainty) -> CertaintyLevel {
    CertaintyLevel(certainty)
  }
}

